#include <vector>
#include <list>
#include <iostream>

int main() {
    std::vector<int> v(1000); // Allocates capacity for 1000
    size_t v_cap = v.capacity();

    v.clear(); // Size is 0, but capacity remains v_cap
    std::cout << "Vector capacity after clear: " << v.capacity() << "\n";

    // Memory is usually freed only via the swap trick
    std::vector<int>().swap(v); 

    // std::list memory is freed immediately upon erase()
    std::list<int> l(1000);
    l.pop_back(); // Memory for one node is freed instantly

    // The container summary table confirms: Vector 'Never' frees memory for removed elements, List 'Always'.
}
